('acc-001', 'Tản nhiệt nước AIO Corsair iCUE LINK H150i LCD 360mm White', 'accessories', 6890000, 7590000, 9, 4.9, 62, 20, 1, 1, 0, 0, 'https://images.unsplash.com/photo-1587202372634-32705e3bf49c?auto=format&fit=crop&w=1200&q=80', 'Hệ sinh thái thông minh iCUE LINK kết nối 1 dây duy nhất, màn hình IPS LCD 2.1 inch hiển thị nhiệt độ hoặc ảnh GIF sống động.', '{"Kích thước Radiator":"360mm (397mm x 120mm x 27mm)","Màn hình":"IPS LCD 2.1 inch (480x480) 60Hz 30fps 600 nits","Quạt tản":"3x QX120 RGB Magnetic Dome Fans","Tốc độ quạt":"480 - 2,400 RPM với chế độ Zero RPM","Hỗ trợ Socket":"Intel LGA 1700/1851, AMD AM5/AM4"}', '["Công nghệ kết nối đơn dây iCUE LINK đi dây siêu gọn gàng","Màn hình IPS LCD hiển thị thông số CPU/GPU thời gian thực hoặc ảnh GIF","Bơm tản nhiệt công suất cao làm mát êm ái cho cả CPU i9 / R9","Phần mềm iCUE đồng bộ hiệu ứng ánh sáng thông minh"]'),
('acc-002', 'Giá Treo 2 Màn Hình Công Thái Học Human Motion T9 Pro Dual', 'accessories', 1890000, 2290000, 17, 4.8, 145, 45, 0, 0, 1, 0, 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=1200&q=80', 'Tay nâng arm màn hình đôi chịu lực siêu khỏe lên đến 15kg mỗi tay, nâng đỡ màn hình lên tới 35 inch, trợ lực lò xo cơ học Gas Spring bền bỉ.', '{"Tải trọng":"3kg - 15kg mỗi tay (Tổng 30kg)","Kích thước màn hỗ trợ":"17 - 35 inch mỗi màn","Chuẩn VESA":"75x75mm và 100x100mm","Góc xoay":"Xoay 360°, gập ngửa +90°/-45°, xoay ngang 180°","Lắp đặt":"Kẹp bàn hoặc khoan lỗ bàn (Bàn dày 10-85mm)"}', '["Chịu tải khủng lên đến 15kg đỡ mượt màn cong lớn 34-35 inch","Piston trợ lực Gas Spring nâng hạ nhẹ nhàng bằng 1 đầu ngón tay","Rãnh giấu dây cáp thông minh giúp bàn làm việc gọn gàng tinh tế","Chất liệu hợp kim nhôm đúc nguyên khối siêu cứng cáp"]'),
('acc-003', 'Ghế Công Thái Học Ergonomic Sihoo Doro C300 Lưới Toàn Thân', 'accessories', 6490000, 7290000, 11, 4.9, 185, 25, 1, 1, 1, 1, 'https://images.unsplash.com/photo-1580481077194-c1598fefad19?auto=format&fit=crop&w=1200&q=80', 'Ghế công thái học bảo vệ cột sống thắt lưng cao cấp, đệm thắt lưng tự động thích ứng chuyển động cơ thể, tay vịn 6D điều chỉnh đa hướng linh hoạt.', '{"Chất liệu":"Lưới mây Polymer Cloud Mesh thoáng khí đàn hồi cao","Đệm thắt lưng":"Cơ chế tự động thích ứng Dynamic Lumbar Support","Kê tay":"Tay vịn 6D xoay đồng bộ theo tư thế ngả lưng","Tựa đầu":"Tựa đầu 3D ôm sát đốt sống cổ","Piston":"Thủy lực Class 4 đạt chuẩn chứng nhận an toàn TUV"}', '["Hệ thống nâng đỡ lưng dưới tự động ôm sát lưng khi ngồi thẳng hay ngả nghiêng","Lưới toàn thân Cloud Mesh mát mẻ không tích tụ nhiệt vào mùa hè","Góc ngả lưng thư giãn 138 độ có kê chân mở rộng ngủ trưa tiện lợi","Chịu tải trọng tối đa lên tới 150 kg cực kỳ vững chắc"]'),
('acc-004', 'Ghế Gaming Da PU Cao Cấp Corsair T3 Rush Charcoal', 'accessories', 5990000, 6690000, 10, 4.8, 95, 16, 0, 0, 1, 0, 'https://images.unsplash.com/photo-1598550476439-6847785fdd52?auto=format&fit=crop&w=1200&q=80', 'Thiết kế lấy cảm hứng từ ghế ngồi xe đua thể thao chuyên nghiệp, bọc vải nỉ cao cấp thoáng khí mát mẻ kết hợp gối đệm mút hoạt tính cao cấp.', '{"Chất liệu":"Vải nỉ thể thao mềm mại thoáng khí chống bám mồ hôi","Khung ghế":"Khung thép cường lực định hình bền bỉ","Kê tay":"Tay vịn 4D nâng hạ, trượt trước sau, xoay trái phải","Góc ngả":"Ngả lưng phẳng 180 độ","Bánh xe":"Bánh xe đôi 65mm chống trầy xước sàn gỗ"}', '["Chất liệu vải nỉ thoáng khí không bị nóng bí bách như da simili rẻ tiền","Gối đệm cổ và đệm thắt lưng bọc nhung êm ái hỗ trợ tư thế ngồi chuẩn","Khả năng ngả lưng 180 độ nghỉ ngơi thư giãn sau những trận game căng thẳng","Khung thép dày dặn đảm bảo độ bền trên 5 năm sử dụng"]'),
('acc-005', 'Micro Thu Âm Chuyên Nghiệp Elgato Wave:3 USB Condenser', 'accessories', 3790000, 4290000, 12, 4.9, 140, 30, 1, 1, 1, 1, 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?auto=format&fit=crop&w=1200&q=80', 'Chiếc micro streaming và podcast tiêu chuẩn vàng của Elgato với công nghệ chống vỡ tiếng độc quyền Clipguard và phần mềm trộn âm Wave Link 9 kênh.', '{"Củ micro":"17mm Electret Condenser Capsule","Định hướng thu":"Cardioid (Thu âm định hướng phía trước)","Tần số lấy mẫu":"24-bit / 96kHz độ phân giải cao","Dải tần đáp ứng":"70 – 20,000 Hz","Kết nối":"Cáp Type-C to Type-A cắm là nhận (Plug & Play)"}', '["Công nghệ độc quyền Clipguard tự động cân bằng âm thanh khi bạn hét lớn","Nút cảm ứng trên đỉnh micro chạm nhẹ là tắt tiếng tức thì (Capacitive Mute)","Phần mềm Wave Link trộn âm thanh chuyên nghiệp từ 9 nguồn âm thanh riêng biệt","Tương thích hoàn hảo với bàn điều khiển Stream Deck"]'),
('acc-010', 'Giá Treo Màn Hình Đôi Human Motion T9 Pro Dual RGB 17-35 inch Piston Gas', 'accessories', 1890000, 2080000, 10, 4.7, 20, 10, 1, 1, 1, 1, 'https://images.unsplash.com/photo-1588508065123-287b28e013da?auto=format&fit=crop&w=1000&q=80', 'Phụ kiện công nghệ cao cấp hỗ trợ góc làm việc chuyên nghiệp - Giá Treo Màn Hình Đôi Human Motion T9 Pro Dual RGB 17-35 inch Piston Gas. Thiết kế hiện đại, độ bền vượt trội, đáp ứng tối đa hiệu năng cho công việc chuyên nghiệp và giải trí đỉnh cao. Đạt tiêu chuẩn kiểm định chất lượng nghiêm ngặt của DANGVINHPC.', '{"Tải trọng":"Mỗi tay nâng chịu lực 15kg","Kích cỡ màn":"Từ 17 inch đến 35 inch","Trợ lực":"Piston khí nén Gas Spring cao cấp","LED":"Đèn RGB viền chân đế"}', '["Sản phẩm chính hãng 100% nguyên seal mới xuất xưởng","Chính sách bảo hành đổi mới uy tín từ nhà phân phối","Được kiểm tra và chạy thử ổn định trước khi giao","Hỗ trợ giao hàng hỏa tốc trong 2 giờ và ship COD toàn quốc"]'),
